
'use strict';
function planView(){
 const p=data.plans.find(x=>x.id===planId),proc=planId===9,rows=items(data,planId), source=base.sources[proc?'procurement':'plans'];
 const cards=proc?
 kpi('กรอบแผนบริหาร',mil(p.budget),'ล้านบาท','กรอบแผนงานที่ 9 หลังปรับ','Wallet','purple')+kpi('วงเงินในทะเบียนจัดซื้อฯ',mil(sum(rows,'budget')),'ล้านบาท',rows.length+' โครงการในทะเบียน','Layers','gold')+kpi('วงเงินอนุมัติจัดซื้อฯ',mil(sum(rows,'allocated')),'ล้านบาท','เฉพาะโครงการในทะเบียน','Banknote','green')+kpi('โครงการลงนามสัญญา',fmt(signed(data)),'โครงการ','จาก '+rows.length+' โครงการจัดซื้อจัดจ้าง','FileSignature','rose'):
 kpi('กรอบวงเงินหลังปรับ',mil(p.budget),'ล้านบาท','กรอบเดิม '+mil(p.originalBudget)+' ล้านบาท','Wallet','purple')+kpi('จัดสรรสะสม',mil(p.allocated),'ล้านบาท',percent(p.allocated,p.budget)+' ของกรอบหลังปรับ','Banknote','green')+kpi('MOU ลงนามแล้ว',fmt(p.mouSigned),'ฉบับ','จาก '+fmt(p.mouTotal)+' ฉบับ · '+percent(p.mouSigned,p.mouTotal),'FileSignature','gold')+kpi('เบิกจ่ายสะสม',mil(p.paid),'ล้านบาท',p.paid==null?'ต้นฉบับยังไม่ระบุยอด':'คิดเป็น '+percent(p.paid,p.allocated)+' ของยอดจัดสรร','Receipt','rose');
 return title('แผนงานที่ '+planId,p.shortName,h(p.name),btn('ส่งออกรายงาน','Download','export')+go('อัปเดตแผนนี้','Upload','import','primary'))+`<div class="kpis">${cards}</div>${proc?procSummary():grantSummary(p)}<article class="box tablebox" id="projects"><div class="cardhead"><div><h2>${proc?'ติดตามโครงการจัดซื้อจัดจ้าง':'ติดตามรายการในแผนงาน'}</h2><p class="sub">เลือกชื่อรายการเพื่อดูสถานะ ผู้รับผิดชอบ และแถวต้นทาง</p></div><span class="chip">${rows.length} ${proc?'โครงการ':'รายการ'}</span></div><div class="filterline"><label class="search">${icon('Search')}<input id="search" type="search" value="${h(filter)}" placeholder="${proc?'ค้นหาโครงการ หรือชื่อเจ้าหน้าที่':'ค้นหารายการ กลุ่ม หรือผู้รับผิดชอบ'}" aria-label="ค้นหารายการ"></label>${proc?`<select id="stagefilter" class="field" aria-label="กรองขั้นตอน"><option value="">ทุกขั้นตอน</option>${stages.map(s=>`<option ${s===stageFilter?'selected':''}>${h(s)}</option>`).join('')}</select>`:''}</div><div id="rows">${rowTable()}</div></article><div class="tinyref">${h(source.file)} · ชีต ${h(source.sheet)} · อัปเดตแผนล่าสุด ${dateTH(p.reportDate||base.asOf)}</div>${proc?ledgerBox():''}`;
}
function grantSummary(p){
 const progress=p.items.filter(r=>r.progress!=null), avg=progress.length?sum(progress,'progress')/progress.length:null;
 return `<div class="grid2 mt"><article class="box"><h2>การจัดสรรงบประมาณ</h2>${facts([['กรอบวงเงินคงเหลือ',money(p.budget-p.allocated)+' บาท'],['จัดสรรต่อกรอบ',percent(p.allocated,p.budget)]])}<p class="sub">มติครั้งที่ 1 ตามต้นฉบับ ${mil(p.round1)} ลบ. · ครั้งที่ 2 ${mil(p.round2)} ลบ.</p></article><article class="box"><h2>การลงนามและผลการดำเนินงาน</h2>${facts([['MOU อยู่ระหว่างดำเนินการ',fmt(p.mouPending)+' ฉบับ'],['ในจำนวนนี้ พร้อมลงนาม',p.mouReady==null?'ยังไม่ระบุ':fmt(p.mouReady)+' ฉบับ']])}<p class="sub">${avg==null?'รอเจ้าหน้าที่รายงานร้อยละผลงานครั้งแรก':`ผลงานเฉลี่ย ${fmt(avg,1)}% เฉพาะ ${progress.length} จาก ${p.items.length} รายการที่แจ้งผล (เฉลี่ยต่อรายการ)`}</p></article></div>${p.notes?.length?`<details class="notebox"><summary>ข้อสังเกตจากข้อมูลตั้งต้น</summary>${p.notes.map(t=>`<p>${h(t)}</p>`).join('')}</details>`:''}`;
}
function procSummary(){
 const rows=data.procurement,counts=stages.map(s=>rows.filter(r=>r.stage===s).length);
 const mx=Math.max(...counts,1);
 return `<div class="grid2 mt"><article class="box"><div class="cardhead"><div><h2>โครงการตามขั้นตอน</h2><p class="sub">เลือกขั้นตอนเพื่อกรองทะเบียนโครงการ</p></div><span class="kicon purple">${icon('Milestone')}</span></div><div class="stagelist">${stages.map((s,i)=>counts[i]?`<button class="stagefilter" data-act="stage" data-stage="${h(s)}"><span>${s}</span><i style="width:${60*counts[i]/mx}px"></i><b>${counts[i]}</b></button>`:'').join('')}</div></article><article class="box"><div class="cardhead"><div><h2>ประเด็นติดตามเจ้าหน้าที่</h2><p class="sub">ข้อมูลตามสถานะล่าสุดของแต่ละโครงการ</p></div><span class="kicon gold">${icon('Users')}</span></div><div class="weekline"><span class="pnum">${counts[0]+counts[1]}</span><div><strong>เตรียมการและจัดทำ TOR</strong><p>ติดตามการเสนอหลักการ ขอบเขตงาน และราคากลาง</p></div></div><div class="weekline"><span class="pnum">${counts[3]}</span><div><strong>รอลงนามสัญญา</strong><p>ตรวจความพร้อมของเอกสารสัญญา</p></div></div><div class="weekline"><span class="pnum">${counts[8]}</span><div><strong>รายงานเสร็จสิ้นแล้ว</strong><p>ตามขั้นตอนที่เจ้าหน้าที่ระบุในทะเบียน</p></div></div></article></div>`;
}
function ledgerBox(){
 const l=base.ledger;
 return `<article class="box mt"><details ${ledgerOpen?'open':''}><summary>ทะเบียนค่าใช้จ่ายแผน 9 · ${h(l.period)}</summary>${facts([['ยอดก่อนหักตามทะเบียน',money(l.gross)+' บาท'],['ยอดสุทธิทั้งทะเบียน',money(l.net)+' บาท'],['เฉพาะวันที่ตัดบัญชีเดือนตุลาคม',money(l.monthGross)+' บาท'],['จำนวนรายการตัดบัญชีในเดือน',l.inMonthCount+' จาก '+l.count+' รายการ']])}<p class="sub">${h(l.note)}</p><div class="tablewrap"><table class="t"><thead><tr><th>วันที่ตัดบัญชี</th><th>รายการ</th><th class="number">ก่อนหัก (บาท)</th><th class="number">สุทธิ (บาท)</th></tr></thead><tbody>${l.rows.map(r=>`<tr><td>${dateTH(r.date)}</td><td>${r.count}</td><td class="number">${money(r.gross)}</td><td class="number">${money(r.net)}</td></tr>`).join('')}</tbody></table></div></details></article>`;
}
function rowTable(){
 const proc=planId===9,needle=filter.trim().toLocaleLowerCase('th'),all=items(data,planId).filter(r=>(!stageFilter||r.stage===stageFilter)&&[r.name,r.id,r.group,r.officer,r.status,r.note].some(v=>String(v??'').toLocaleLowerCase('th').includes(needle)));
 const pages=Math.max(1,Math.ceil(all.length/12));page=Math.max(1,Math.min(page,pages));
 const rows=all.slice(12*(page-1),12*page);
 return `<div class="tablewrap"><table class="t"><thead><tr><th>${proc?'โครงการ':'รายการ'}</th><th>${proc?'ขั้นตอน':'จัดสรร (บาท)'}</th><th>${proc?'ผู้ดำเนินการ':'ลงนาม MOU'}</th><th>${proc?'อนุมัติ (บาท)':'ผลงาน'}</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td class="detailname"><button class="textbtn" data-act="item" data-id="${h(r.id)}">${h(r.name)}</button><small>${h(r.id)}</small></td>${proc?`<td>${badge(r.stage,stages.indexOf(r.stage)>=4?'green':r.stage===stages[0]?'purple':'gold')}</td><td class="officer">${h(r.officer?.split(' / ')[0]||'ยังไม่ระบุ')}${r.officer?.includes(' / ')?`<small class="tdsmall">และอีก ${r.officer.split(' / ').length-1} คน</small>`:''}</td><td class="number">${money(r.allocated)}</td>`:`<td class="number">${money(r.allocated)}</td><td>${r.mouSigned==null?'—':fmt(r.mouSigned)+' ฉบับ'}</td><td>${r.progress==null?'—':fmt(r.progress,1)+'%'}</td>`}<td><button class="utility" data-act="item" data-id="${h(r.id)}" aria-label="รายละเอียด ${h(r.id)}">${icon('ChevronRight')}</button></td></tr>`).join('')}</tbody></table></div>${!rows.length?'<p class="emptystate">ไม่พบรายการที่ตรงกับตัวกรอง</p>':''}<div class="pages"><span>แสดง ${all.length?(page-1)*12+1:0}–${Math.min(page*12,all.length)} จาก ${all.length} รายการ</span><div class="flex">${btn('','ChevronLeft','prev','iconbtn',page===1?'disabled aria-label="หน้าก่อน"':'aria-label="หน้าก่อน"')}<span style="padding:0 9px">${page} / ${pages}</span>${btn('','ChevronRight','next','iconbtn',page===pages?'disabled aria-label="หน้าถัดไป"':'aria-label="หน้าถัดไป"')}</div></div>`;
}
function itemDialog(id){
 const r=items(data,planId).find(x=>x.id===id),proc=planId===9,source=base.sources[proc?'procurement':'plans'];
 if(!r)return;
 const info=proc?[['ขั้นตอนปัจจุบัน',r.stage],['วงเงินโครงการ',money(r.budget)+' บาท'],['วงเงินอนุมัติจัดซื้อจัดจ้าง',money(r.allocated)+' บาท'],['เลขที่สัญญา',r.contract],['วันลงนามสัญญา',r.contractDate?dateTH(r.contractDate):r.contractDateRaw],['ผู้ดำเนินการ',r.officer]]:[['กลุ่มรายการ',r.group],['กรอบวงเงินตามแถว',money(r.budget)+' บาท'],['จัดสรรสะสม',money(r.allocated)+' บาท'],['เบิกจ่ายสะสม',money(r.paid)+' บาท'],['MOU ลงนามแล้ว',fmt(r.mouSigned)+' ฉบับ'],['MOU อยู่ระหว่างดำเนินการ',fmt(r.mouPending)+' ฉบับ'],['MOU พร้อมลงนาม',fmt(r.mouReady)+' ฉบับ'],['ผู้รับผิดชอบ',r.officer]];
 modal('รายละเอียด'+(proc?'โครงการ':'รายการ'),`<span class="ftag">แผนงานที่ ${planId} · ${h(id)}</span><h3>${h(r.name)}</h3>${proc?`<p class="hint"><b>สถานะตามรายงาน</b><br>${h(r.status||'ยังไม่รายงาน')}</p>`:''}${facts([...info,['ผลงานที่เจ้าหน้าที่รายงาน',r.progress==null?null:fmt(r.progress,1)+'%'],['ข้อมูล ณ วันที่',dateTH(r.reportDate||base.asOf)]])}<p><b>ความคืบหน้าและงานถัดไป</b><br>${h(r.note||'ยังไม่มีบันทึกรายสัปดาห์')}</p>${r.evidence?`<p class="long"><b>หลักฐานอ้างอิง</b><br>${h(r.evidence)}</p>`:''}<div class="tinyref">ต้นทาง ${h(source.file)} · ชีต ${h(source.sheet)} · แถว ${r.sourceRow}${r.updatedFrom?'<br>อัปเดตล่าสุดจาก '+h(r.updatedFrom):''}</div>`);
}
function weeklyView(){
 const index=dates.indexOf(asOf),prevDate=dates[index+1],old=prevDate?snapshot(base,events,prevDate):null,gr=support(data),g0=old?support(old):[],alloc=sum(gr,'allocated'),mou=sum(gr,'mouSigned'),thisRound=events.filter(e=>e.date===asOf), most=[...gr].sort((a,b)=>(b.budget-b.allocated)-(a.budget-a.allocated))[0];
 const diff=(v,u)=>`${v>0?'+':''}${u==='ลบ.'?mil(v):fmt(v)} ${u}`;
 return title('สำหรับผู้จัดการกองทุนฯ','รายงานความคืบหน้ารายสัปดาห์','รอบวันที่ '+dateTH(asOf,true)+(old?' · เปรียบเทียบรอบ '+dateTH(prevDate):' · รอบฐานจากทะเบียนต้นทาง'),btn('ส่งออกรายงาน','Download','export','primary'))+`<div class="grid2"><article class="box"><h2>ความเคลื่อนไหวรอบนี้</h2>${facts([['วงเงินจัดสรรแผน 1–5',mil(alloc)+' ล้านบาท'],['เปลี่ยนจากรอบก่อน',old?diff(alloc-sum(g0,'allocated'),'ลบ.'):'รอรอบเปรียบเทียบ'],['MOU ลงนามสะสม',fmt(mou)+' ฉบับ'],['เปลี่ยนจากรอบก่อน',old?diff(mou-sum(g0,'mouSigned'),'ฉบับ'):'รอรอบเปรียบเทียบ']])}</article><article class="box"><h2>ประเด็นสำหรับการประชุม</h2><div class="weekline"><span class="kicon gold">${icon('Wallet')}</span><div><strong>แผน ${most.id} มีกรอบคงเหลือสูงสุด</strong><p>${mil(most.budget-most.allocated)} ล้านบาท จากกรอบ ${mil(most.budget)} ล้านบาท</p></div></div><div class="weekline"><span class="kicon purple">${icon('FileSignature')}</span><div><strong>MOU พร้อมลงนามที่มีรายงาน ${sum(gr,'mouReady')} ฉบับ</strong><p>อยู่ในยอดระหว่างดำเนินการของแต่ละแผน</p></div></div><div class="weekline"><span class="kicon green">${icon('ClipboardList')}</span><div><strong>แผน 9 ลงนามสัญญาแล้ว ${signed(data)} จาก ${data.procurement.length} โครงการ</strong><p>${old?'เปลี่ยนจากรอบก่อน '+diff(signed(data)-signed(old),'โครงการ'):'ติดตามขั้นตอนและเจ้าหน้าที่รายโครงการได้ในแผน 9'}</p></div></div></article></div>
 <article class="box tablebox"><div class="cardhead"><div><h2>สถานะรายแผน ณ รอบที่เลือก</h2><p class="sub">แผนที่ยังไม่มีรายงานรอบใหม่แสดงข้อมูลล่าสุดพร้อมวันที่อ้างอิง</p></div></div><div class="tablewrap"><table class="t"><thead><tr><th>แผนงาน</th><th>ปรับปรุงล่าสุด</th><th>ตัวชี้วัด</th><th>เปลี่ยนจากรอบก่อน</th></tr></thead><tbody>${data.plans.map(p=>{const proc=p.id===9,prior=old?.plans.find(x=>x.id===p.id);return `<tr><td><a href="#plan/${p.id}">แผน ${p.id} · ${h(planLabels[p.id])}</a></td><td>${dateTH(p.reportDate||base.asOf)}</td><td>${proc?'สัญญาลงนาม '+signed(data)+' โครงการ':'จัดสรร '+mil(p.allocated)+' ลบ. · ลงนาม '+fmt(p.mouSigned)+' ฉบับ'}</td><td>${old?(proc?diff(signed(data)-signed(old),'โครงการ'):diff(p.allocated-prior.allocated,'ลบ.')+' / '+diff(p.mouSigned-prior.mouSigned,'ฉบับ')):'—'}</td></tr>`}).join('')}</tbody></table></div></article><article class="box mt"><h2>บันทึกการนำเข้าในรอบ</h2>${thisRound.length?thisRound.map(ev=>`<div class="historyrow"><span class="pnum">0${ev.planId}</span><div>${h(ev.file)}<span class="tdsmall">${ev.rows.length} รายการที่อัปเดต</span></div><button class="textbtn meta" data-act="log" data-ev="${events.indexOf(ev)}">ดูรายการ ${icon('ArrowUpRight')}</button></div>`).join(''):`<p class="sub">ใช้ข้อมูลตั้งต้นจากทะเบียนแผนงานและจัดซื้อจัดจ้าง ณ ${dateTH(base.asOf)}</p>`}</article>`;
}
function sourcesView(){
 return title('ข้อมูลอ้างอิง','แหล่งข้อมูลและวิธีคำนวณ','ตรวจสอบทะเบียนต้นทาง ความหมายของตัวชี้วัด และข้อสังเกตสำหรับการอ่านรายงาน')+Object.entries(base.sources).map(([k,s])=>`<article class="box sourcecard"><span class="ftag">${icon('FileSpreadsheet')}${{plans:'งบประมาณและ MOU',procurement:'จัดซื้อจัดจ้าง',ledger:'ทะเบียนค่าใช้จ่าย'}[k]}</span><b>${h(s.file)}</b><p class="sub">ชีต ${h(s.sheet)} · ${dateTH(s.asOf)}</p><p>${h(s.columns)}</p><p class="sub">${h(s.note)}</p></article>`).join('')+`<article class="box mt"><h2>ฐานคำนวณและการติดตาม</h2><p class="sub">สัดส่วนจัดสรร = ยอดอนุมัติสะสม ÷ กรอบวงเงินหลังปรับ ส่วนสัดส่วนเบิกจ่ายในหน้ารายแผนใช้ยอดจัดสรรเป็นฐาน ร้อยละ MOU ใช้จำนวนลงนาม ÷ จำนวนรวมตามทะเบียน ร้อยละผลงานมาจากข้อมูลที่เจ้าหน้าที่รายงาน</p><p class="sub">การอัปเดตยอดสะสมอ้างอิงรหัสรายการเดิม ใช้ผลต่างจากค่าก่อนหน้าเพื่อรักษายอดสรุปของต้นฉบับ หากระบุยอดรวมในแถว Pn-TOTAL ระบบใช้ยอดนั้นเป็นยอดของแผนในรอบที่เลือก เครื่องหมาย — หมายถึงยังไม่ระบุค่า</p>${base.plans.flatMap(p=>p.notes.map(n=>`<p class="notebox"><b>แผน ${p.id}</b> · ${h(n)}</p>`)).join('')}</article><article class="box mt"><h2>กระบวนการจัดซื้อจัดจ้างภาครัฐ</h2><p class="sub">หน้าติดตามจัดกลุ่มข้อความในทะเบียนตามขั้นตอนปฏิบัติงาน เจ้าหน้าที่เลือกขั้นตอนที่ตรงกับวิธีจัดซื้อจัดจ้างและหลักฐานของโครงการได้</p><div class="flow">${stages.map(s=>`<span>${h(s)}</span>`).join('')}</div><div class="sourceslist mt"><a href="https://nsdf.or.th/content/d3b61b21-34f1-44e1-9ddb-c97a654ab30b" target="_blank" rel="noopener">หลักเกณฑ์ วิธีการ และเงื่อนไขในการให้ทุนฯ · กองทุนพัฒนาการกีฬาแห่งชาติ ${icon('ExternalLink')}</a><a href="${refLink}" target="_blank" rel="noopener">แนวทางจัดซื้อจัดจ้างวิธีเฉพาะเจาะจง · กรมควบคุมโรค ${icon('ExternalLink')}</a><a href="${refAccept}" target="_blank" rel="noopener">ขั้นตอนการจัดซื้อ การตรวจรับ และการเบิกจ่าย · กรมอนามัย ${icon('ExternalLink')}</a></div></article>`;
}
function importView(){
 return title('จัดการข้อมูลรายสัปดาห์','นำเข้าและเทมเพลต','ดาวน์โหลดเทมเพลตของแผนงาน กรอกเฉพาะข้อมูลที่เปลี่ยน แล้วตรวจผลก่อนบันทึกรอบรายงาน')+`<div class="grid2"><article class="box importform"><div class="cardhead"><div><h2>นำเข้าความคืบหน้า</h2><p class="sub">ไฟล์ Excel ตามเทมเพลตของแผนงาน</p></div><span class="kicon purple">${icon('Upload')}</span></div><div class="grid2"><label>แผนงาน<select id="importplan" class="field">${base.plans.map(p=>`<option value="${p.id}" ${p.id===importPlan?'selected':''}>แผน ${p.id} · ${planLabels[p.id]}</option>`).join('')}</select></label><label>วันที่รายงาน<input type="date" class="field" id="importdate" value="${h(importDate)}" min="${dates[0]}" max="${NSDF.localDate()}"></label></div><label class="droptarget" id="drop">${icon('FileSpreadsheet')}<strong>เลือกไฟล์ หรือลากไฟล์มาวาง</strong><small class="muted">.xlsx ขนาดไม่เกิน 10 MB</small><input type="file" id="file" accept=".xlsx" aria-label="เลือกไฟล์อัปเดต Excel"></label><div id="preview" aria-live="polite"><p class="sub">ช่องที่เว้นว่างจะใช้ค่าเดิม ระบบจับคู่ข้อมูลตามรหัสรายการ</p></div>${browserStorage?'<p class="hint">รอบที่นำเข้าจะบันทึกในเบราว์เซอร์นี้บนอุปกรณ์นี้</p>':''}</article><article class="box"><div class="cardhead"><div><h2>เทมเพลตประจำแผน</h2><p class="sub">มีรหัสรายการจากทะเบียน และชีตวิธีกรอก</p></div><span class="kicon green">${icon('FolderOpen')}</span></div><div class="tpllist">${base.plans.map(p=>`<a href="templates/plan-${p.id}.xlsx" download="เทมเพลตแผนงานที่-${p.id}-2570.xlsx"><span class="pnum">0${p.id}</span><span>${h(p.shortName)}</span>${icon('Download')}</a>`).join('')}</div></article></div><article class="box mt"><h2>ประวัติการนำเข้า</h2>${events.length?[...events].reverse().map(e=>`<div class="historyrow"><span class="pnum">0${e.planId}</span><div>${h(e.file)}<p class="sub">รอบ ${dateTH(e.date)} · ${e.rows.length} รายการ</p></div><button class="textbtn meta" data-act="log" data-ev="${events.indexOf(e)}">ดูรายการ ${icon('ArrowUpRight')}</button></div>`).join(''):`<p class="sub">รอบฐาน ${dateTH(base.asOf)} · ยังไม่มีการนำเข้าไฟล์รายสัปดาห์</p>`}</article>`;
}

